function formatLabel(customer, total) {
  return `${customer}: $${total.toFixed(2)}`;
}

const addTax = function (subtotal, rate) {
  return subtotal * (1 + rate);
};

const double = (value) => value * 2;

console.log(formatLabel("Mina", 10)); // Mina: $10.00
console.log(addTax(10, 0.1));        // 11
console.log(double(6));              // 12

const name = "Alex";

function start() {
  const name = "John";
  return function greet() {
    return name;
  };
}

const greet = start();

function callGreet() {
  const name = "Sam";
  return greet();
}

console.log(callGreet()); // "John"

function createCounter() {
  let count = 0;
  return function increment() {
    count += 1;
    return count;
  };
}

const first = createCounter();
const second = createCounter();

console.log(first());  // 1
console.log(first());  // 2
console.log(second()); // 1

