const amounts = [12, 5, 20, 8];
const expensive = amounts.filter((amount) => amount >= 10);
const labels = expensive.map((amount) => "$" + amount.toFixed(2));

console.log(expensive); // [12, 20]
console.log(labels);   // ["$12.00", "$20.00"]

const users = [{ id: 1, name: "Ayla", active: true }, { id: 2, name: "Omar", active: false }, { id: 3, name: "Mina", active: true }];
const activeCards = users
  .filter((user) => user.active)
  .map(({ id, name }) => ({ id, label: name }));
console.log(activeCards); // [{ id: 1, label: "Ayla" }, { id: 3, label: "Mina" }]

const prices = [12, 8, 5];
const total = prices.reduce((sum, price) => sum + price, 0);
console.log(total); // 25

const emptyTotal = [].reduce((sum, price) => sum + price, 0);
console.log(emptyTotal); // 0

const user = { id: 7, name: "Ayla", role: "editor" };
const { id, name: displayName, role = "viewer" } = user;
const updatedUser = { ...user, role: "admin" };
const { role: currentRole, ...publicProfile } = updatedUser;

console.log(id, displayName, role); // 7 Ayla editor
console.log(currentRole, publicProfile); // admin { id: 7, name: "Ayla" }

